#!/usr/bin/env node
// claim-ladder.js — benchmark the per-tier operations behind the claim ladder.
//
// Measures the agenticow primitives the tier examples are built on, with real
// numbers on this machine: fork (exact + native), score (read-through query),
// promote, contradiction-check, and per-branch storage.
//
// Honesty: these are MECHANICS benchmarks (latency + storage of branch ops). The
// "cognitive quality" of any evolved/ensembled branch is NOT measured here.
//
// Usage: node bench/claim-ladder.js   (env: BASE, DIM, N)

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { performance } from 'node:perf_hooks';
import { open } from '../src/index.js';

const DIM = Number(process.env.DIM || 64);
const BASE = Number(process.env.BASE || 5000);
const N = Number(process.env.N || 200);
const REPEAT = Number(process.env.REPEAT || 5);

const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'agenticow-ladder-'));
let s = 42;
const rnd = () => { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff * 2 - 1; };
const vec = () => Float32Array.from({ length: DIM }, rnd);
const cos = (a, b) => { let d = 0, na = 0, nb = 0; for (let i = 0; i < DIM; i++) { d += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; } return 1 - d / (Math.sqrt(na) * Math.sqrt(nb)); };
const median = (xs) => { const t = [...xs].sort((a, b) => a - b); return t[Math.floor(t.length / 2)]; };
const fmt = (ms) => ms < 1 ? `${(ms * 1000).toFixed(0)} µs` : `${ms.toFixed(3)} ms`;

console.log('agenticow — claim-ladder operation benchmark');
console.log('='.repeat(64));
console.log(`machine: ${os.cpus()[0].model.trim()} (${os.cpus().length} threads)`);
console.log(`node   : ${process.version}   base=${BASE} dim=${DIM} N=${N}`);
console.log('='.repeat(64));

const base = open(path.join(dir, 'base.rvf'), { dimension: DIM });
const flat = new Float32Array(BASE * DIM);
for (let i = 0; i < BASE; i++) flat.set(vec(), i * DIM);
base.ingest(flat, Array.from({ length: BASE }, (_, i) => i));
const target = vec();

// fork (exact)
const forkExact = [];
const forks = [];
for (let i = 0; i < N; i++) { const t = performance.now(); const f = base.fork(`e${i}`); forkExact.push(performance.now() - t); f.ingest([{ id: 9e6 + i, vector: vec() }]); forks.push(f); }

// fork (native ANN, if available)
let nativeOn = false; const forkNative = [];
for (let i = 0; i < Math.min(N, 50); i++) {
  const t = performance.now();
  const f = base.fork(`n${i}`, undefined, { nativeAnn: true });
  forkNative.push(performance.now() - t);
  nativeOn = f.nativeAnn;
  f.close();
}

// score (read-through query of target, modest k)
const scoreLat = [];
for (let r = 0; r < REPEAT; r++) for (const f of forks) { const t = performance.now(); f.query(target, 10); scoreLat.push(performance.now() - t); }

// promote
const promoteLat = [];
for (let i = 0; i < Math.min(N, 50); i++) { const t = performance.now(); forks[i].promote(base); promoteLat.push(performance.now() - t); }

// contradiction-check: compare M branch facts pairwise at one shared id
const M = Math.min(N, 50);
const factVecs = forks.slice(0, M).map(() => vec());
const tC = performance.now();
let contradictions = 0, pairs = 0;
for (let i = 0; i < M; i++) for (let j = i + 1; j < M; j++) { pairs++; if (cos(factVecs[i], factVecs[j]) > 0.3) contradictions++; }
const contradictionMs = performance.now() - tC;

// storage
let branchBytes = 0;
for (const f of forks) branchBytes += fs.statSync(f.lineage()[0].path).size;
const perBranch = branchBytes / forks.length;

const rows = [
  ['fork (exact, derive)', fmt(median(forkExact)), `${Math.round(1000 / median(forkExact))}/s`],
  [`fork (native ANN${nativeOn ? '' : ', fallback→exact'})`, fmt(median(forkNative)), `${Math.round(1000 / median(forkNative))}/s`],
  ['score (read-through query k=10)', fmt(median(scoreLat)), `${Math.round(1000 / median(scoreLat))}/s`],
  ['promote (replay delta)', fmt(median(promoteLat)), `${Math.round(1000 / median(promoteLat))}/s`],
  [`contradiction-check (${pairs} pairs)`, fmt(contradictionMs), `${Math.round(pairs / (contradictionMs / 1000)).toLocaleString()} pairs/s`],
];

console.log('\noperation                                 p50           throughput');
console.log('-'.repeat(64));
for (const [op, p50, tp] of rows) console.log(`${op.padEnd(42)}${p50.padStart(8)}     ${tp}`);
console.log('-'.repeat(64));
console.log(`per-branch storage : ${(perBranch / 1024).toFixed(2)} KB (${forks.length} branches, ${(branchBytes / 1024).toFixed(1)} KB total)`);
console.log(`native ANN active  : ${nativeOn} (linux-x64-gnu; graceful exact fallback elsewhere)`);
console.log(`contradictions     : ${contradictions}/${pairs} pairs over threshold`);

const out = {
  machine: os.cpus()[0].model.trim(), node: process.version, base: BASE, dim: DIM, n: N, date: new Date().toISOString(),
  forkExactMs: median(forkExact), forkNativeMs: median(forkNative), nativeAnnActive: nativeOn,
  scoreMs: median(scoreLat), promoteMs: median(promoteLat),
  contradictionPairsPerSec: Math.round(pairs / (contradictionMs / 1000)),
  perBranchBytes: perBranch,
};
try { fs.writeFileSync(path.join(process.cwd(), 'bench', 'claim-ladder-results.json'), JSON.stringify(out, null, 2)); console.log('\nwrote bench/claim-ladder-results.json'); } catch { /* */ }

base.close(); forks.forEach((f) => { try { f.close(); } catch { /* */ } });
fs.rmSync(dir, { recursive: true, force: true });

// Type declarations for agenticow — Git for Agent Memory.

export interface OpenOptions {
  /** Vector dimension. Required when creating a new memory file. */
  dimension?: number;
  /** Distance metric. Default: "cosine". */
  metric?: string;
  /** HNSW M parameter (optional, create only). */
  m?: number;
  /** HNSW efConstruction (optional, create only). */
  efConstruction?: number;
  /** Keep an in-memory edit log enabling diff()/promote(). Default: true. */
  track?: boolean;
}

export interface MemoryDiff {
  added: number[];
  overridden: number[];
  deleted: number[];
}

export interface IngestResult {
  accepted: number;
  rejected: number;
  epoch: number;
}

export interface QueryOptions {
  /** HNSW efSearch passed to each store in the lineage chain. */
  efSearch?: number;
  /** Candidates to over-fetch per store before exact merge. Default: k*4. */
  overscan?: number;
  /**
   * Force the exact JS chain-walk even on a native-COW fork.
   * Default false (native path used when available).
   */
  forceExact?: boolean;
}

export interface ForkOptions {
  /**
   * Use the native Rust COW dual-graph ANN path (PR #618).
   * When true, fork() calls RvfDatabase.branch() instead of derive(), giving
   * the returned fork a working node whose query() spans the COW boundary in
   * a single Rust call. recall@10 = 1.0 at 1200-vector L2 test corpus.
   * Default: false (exact JS chain-walk).
   */
  nativeAnn?: boolean;
}

export interface QueryHit {
  id: number;
  distance: number;
  /** label/id of the lineage node the hit came from (which "wins"). */
  branch: string;
  /** optional text/payload set via ingest(vec,{text}) / ingest([{id,vector,text}]). */
  text?: string;
}

export interface IngestPayload {
  /** explicit id; auto-assigned when omitted. */
  id?: number;
  /** optional text/payload stored for this id, surfaced on query hits. */
  text?: string;
}

export interface QueryOptionsTopK extends QueryOptions {
  /** number of nearest neighbors to return (alias of the positional `k`). */
  topK?: number;
  k?: number;
}

export interface CheckpointDescriptor {
  id: string;
  label: string;
  path: string;
  depth: number;
}

export interface LineageNode {
  role: 'working' | 'checkpoint' | 'base';
  id: string;
  label: string | null;
  path: string;
  /** fileId of the parent node (null for the base). */
  parent: string | null;
  /** epoch ms when this node was created. */
  createdAt: number;
  /** number of ids ingested at this node (requires track). */
  mutations: number;
  tombstones: number;
}

export interface MemoryStatus {
  totalVectors: number;
  totalSegments: number;
  fileSize: number;
  currentEpoch: number;
  profileId: number;
  compactionState: string;
  deadSpaceRatio: number;
  readOnly: boolean;
  chainDepth: number;
  dimension: number;
  metric: string;
}

export type IngestRecord = { id: number; vector: number[] | Float32Array; text?: string };

export class AgenticMemory {
  static open(filePath: string, opts?: OpenOptions): AgenticMemory;
  readonly dimension: number;
  /**
   * True when this fork was created with `{nativeAnn:true}`.
   * query() routes through the Rust dual-graph ANN merge (PR #618).
   */
  readonly nativeAnn: boolean;
  ingest(records: IngestRecord[]): IngestResult;
  ingest(vectors: Float32Array, ids: number[]): IngestResult;
  /** Convenience single-vector form: ingest(vec, { text?, id? }). Auto-ids when omitted. */
  ingest(vector: number[] | Float32Array, payload?: IngestPayload): IngestResult;
  delete(ids: number[]): { deleted: number; tombstoned: number };
  query(vector: number[] | Float32Array, k?: number, opts?: QueryOptions): QueryHit[];
  /** Convenience options form: query(vec, { topK, efSearch?, overscan? }). */
  query(vector: number[] | Float32Array, opts: QueryOptionsTopK): QueryHit[];
  branch(label?: string, filePath?: string): AgenticMemory;
  fork(label?: string, filePath?: string, opts?: ForkOptions): AgenticMemory;
  diff(): MemoryDiff;
  /** Promote this branch's edits into `target`; defaults to the fork/branch parent when omitted. */
  promote(target?: AgenticMemory): { ingested: number; deleted: number };
  checkpoint(label?: string): CheckpointDescriptor;
  rollback(checkpointId?: string): { restoredTo: string; depth: number };
  lineage(): LineageNode[];
  status(): MemoryStatus;
  save(manifestPath: string): string;
  static load(manifestPath: string): AgenticMemory;
  close(): void;
}

export function open(filePath: string, opts?: OpenOptions): AgenticMemory;
/** Alias of {@link open}; lets `import { openBase }` snippets run verbatim. */
export function openBase(filePath: string, opts?: OpenOptions): AgenticMemory;

declare const _default: {
  open: typeof open;
  openBase: typeof openBase;
  AgenticMemory: typeof AgenticMemory;
};
export default _default;

#!/usr/bin/env node
// agenticow ACCEPTANCE TEST — the headline proof.
//
// Spec (run exactly, report real numbers):
//   1. Create 1 base RVF, fork N branches (target N=1000).
//   2. Per branch: insert new vectors + tombstone some base vectors.
//   3. Prove top-K correctness after masking + reranking: for a sample of
//      branches, query top-K via agenticow read-through and assert it matches a
//      brute-force exact ground truth (base ∪ inserts − tombstones, reranked by
//      distance). Report recall/exactness.
//   4. Rollback any branch instantly — measure rollback latency (~constant).
//   5. Show total storage grows with DELTA size, not base size — bytes(N
//      branches) vs bytes(base) vs N×full-copy. Prove sublinear-in-base.
//
// Honesty: read-through is the EXACT path (parent ∪ edits, child wins, deletes
// honored). A single ANN index spanning the COW boundary is roadmap; this test
// proves exact correctness of the read-through merge. If forking N branches hits
// a real limit (fd/memory/time), the max that worked + the scaling curve are
// reported — the 1000 is not faked.
//
// Usage:
//   node bench/acceptance.js                 # base=20k, branches=1000 (default)
//   BASE=50000 BRANCHES=1000 DIM=128 node bench/acceptance.js

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { performance } from 'node:perf_hooks';
import { open } from '../src/index.js';

const DIM = Number(process.env.DIM || 128);
const BASE = Number(process.env.BASE || 20000);
const BRANCHES = Number(process.env.BRANCHES || 1000);
const INSERTS_PER_BRANCH = Number(process.env.INSERTS || 8);
const TOMBSTONES_PER_BRANCH = Number(process.env.TOMBS || 4);
const SAMPLE = Number(process.env.SAMPLE || 40); // branches to verify for correctness
const K = Number(process.env.K || 10);

const workDir = fs.mkdtempSync(path.join(os.tmpdir(), 'agenticow-acc-'));
const basePath = path.join(workDir, 'base.rvf');

function rndVec() {
  const v = new Float32Array(DIM);
  for (let i = 0; i < DIM; i++) v[i] = Math.random() * 2 - 1;
  return v;
}
function cosineDist(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < DIM; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  const den = Math.sqrt(na) * Math.sqrt(nb);
  return den === 0 ? 1 : 1 - dot / den;
}
function fmtBytes(b) {
  if (b < 1024) return `${b} B`;
  if (b < 1024 * 1024) return `${(b / 1024).toFixed(1)} KB`;
  if (b < 1024 * 1024 * 1024) return `${(b / 1024 / 1024).toFixed(1)} MB`;
  return `${(b / 1024 / 1024 / 1024).toFixed(2)} GB`;
}
function median(xs) { const s = [...xs].sort((a, b) => a - b); return s[Math.floor(s.length / 2)]; }
function dirSize(dir, filter) {
  let total = 0;
  for (const f of fs.readdirSync(dir)) {
    if (filter && !filter(f)) continue;
    try { total += fs.statSync(path.join(dir, f)).size; } catch { /* */ }
  }
  return total;
}

async function main() {
  console.log('agenticow — ACCEPTANCE TEST');
  console.log('='.repeat(72));
  console.log(`machine : ${os.cpus()[0].model.trim()} (${os.cpus().length} threads)`);
  console.log(`node    : ${process.version}  platform: ${process.platform}-${process.arch}`);
  console.log(`config  : base=${BASE.toLocaleString()} vectors  target branches=${BRANCHES}  dim=${DIM}`);
  console.log(`        : ${INSERTS_PER_BRANCH} inserts + ${TOMBSTONES_PER_BRANCH} tombstones / branch`);
  console.log('='.repeat(72));

  // ---- 1. Base ----
  process.stdout.write(`\n[1] building base of ${BASE.toLocaleString()} vectors ... `);
  const baseVecs = []; // keep ground-truth copies (base is small enough for the test)
  const base = open(basePath, { dimension: DIM, metric: 'cosine', track: false });
  const BATCH = 10000;
  for (let off = 0; off < BASE; off += BATCH) {
    const m = Math.min(BATCH, BASE - off);
    const flat = new Float32Array(m * DIM);
    const ids = new Array(m);
    for (let i = 0; i < m; i++) {
      const v = rndVec();
      flat.set(v, i * DIM);
      ids[i] = off + i;
      baseVecs.push(v);
    }
    base.ingest(flat, ids);
  }
  const baseBytes = fs.statSync(basePath).size;
  console.log(`${fmtBytes(baseBytes)}`);

  // ---- 2. Fork N branches with inserts + tombstones ----
  // Ground truth per branch: { inserts: Map(id->vec), tombstones: Set(id) }
  process.stdout.write(`[2] forking branches (insert + tombstone each) ... `);
  const branches = [];
  const truth = [];
  let maxForked = 0;
  const forkLat = [];
  const tFork0 = performance.now();
  try {
    for (let b = 0; b < BRANCHES; b++) {
      const tf = performance.now();
      const br = base.fork(`u${b}`);
      forkLat.push(performance.now() - tf);
      const inserts = new Map();
      for (let i = 0; i < INSERTS_PER_BRANCH; i++) {
        const id = 1_000_000_000 + b * 1000 + i; // unique new id space per branch
        const v = rndVec();
        br.ingest([{ id, vector: v }]);
        inserts.set(id, v);
      }
      const tombs = new Set();
      for (let i = 0; i < TOMBSTONES_PER_BRANCH; i++) {
        const id = (b * 7 + i * 13) % BASE; // deterministic spread over base ids
        tombs.add(id);
      }
      br.delete([...tombs]);
      branches.push(br);
      truth.push({ inserts, tombstones: tombs });
      maxForked = b + 1;
      if ((b + 1) % 200 === 0) process.stdout.write(`${b + 1} `);
    }
  } catch (e) {
    console.log(`\n    ! hit a limit at ${maxForked} branches: ${e.message}`);
    console.log(`    reporting results for the ${maxForked} branches that succeeded.`);
  }
  const forkWallMs = performance.now() - tFork0;
  const N = maxForked;
  console.log(`\n    forked ${N} branches in ${forkWallMsFmt(forkWallMs)} ` +
    `(median ${median(forkLat).toFixed(3)} ms/fork)`);

  // ---- 3. Top-K correctness vs brute-force ground truth ----
  process.stdout.write(`[3] verifying top-${K} correctness on ${Math.min(SAMPLE, N)} sampled branches ... `);
  let exactMatches = 0;
  let recallSum = 0;
  let checks = 0;
  const sampleIdxs = [];
  for (let s = 0; s < Math.min(SAMPLE, N); s++) sampleIdxs.push(Math.floor((s * N) / Math.min(SAMPLE, N)));
  for (const bi of sampleIdxs) {
    const br = branches[bi];
    const t = truth[bi];
    // a few query vectors per branch: one near an insert, one near a base vec, one random
    const queries = [];
    const anyInsert = [...t.inserts.values()][0];
    if (anyInsert) queries.push(anyInsert);
    queries.push(baseVecs[(bi * 17) % BASE]);
    queries.push(rndVec());
    for (const q of queries) {
      // ground truth: brute force over (base − tombstones) ∪ inserts
      const cand = [];
      for (let id = 0; id < BASE; id++) {
        if (t.tombstones.has(id)) continue;
        cand.push({ id, distance: cosineDist(q, baseVecs[id]) });
      }
      for (const [id, v] of t.inserts) cand.push({ id, distance: cosineDist(q, v) });
      cand.sort((a, b) => a.distance - b.distance);
      const gold = cand.slice(0, K).map((c) => c.id);

      const got = br.query(q, K).map((h) => h.id);
      const goldSet = new Set(gold);
      const inter = got.filter((id) => goldSet.has(id)).length;
      recallSum += inter / K;
      if (gold.length === got.length && gold.every((id, i) => id === got[i])) exactMatches++;
      checks++;
    }
  }
  const recall = recallSum / checks;
  const exactRate = exactMatches / checks;
  console.log(`done`);
  console.log(`    recall@${K} = ${(recall * 100).toFixed(1)}%   ` +
    `exact-order match = ${(exactRate * 100).toFixed(1)}%   (${checks} queries)`);

  // verify tombstone masking explicitly: a tombstoned base id must never appear
  let maskViolations = 0;
  for (const bi of sampleIdxs) {
    const t = truth[bi];
    const br = branches[bi];
    for (const tid of t.tombstones) {
      const hits = br.query(baseVecs[tid], 3).map((h) => h.id);
      if (hits.includes(tid)) maskViolations++;
    }
  }
  console.log(`    tombstone masking: ${maskViolations === 0 ? 'PASS' : 'FAIL'} ` +
    `(${maskViolations} leaked tombstones)`);

  // ---- 4. Rollback latency ----
  process.stdout.write(`[4] rollback latency (checkpoint, poison, rollback) ... `);
  const rbLat = [];
  const rbSample = Math.min(50, N);
  for (let s = 0; s < rbSample; s++) {
    const br = branches[Math.floor((s * N) / rbSample)];
    const ck = br.checkpoint('clean');
    for (let i = 0; i < 20; i++) br.ingest([{ id: 2_000_000_000 + s * 100 + i, vector: rndVec() }]);
    const tr = performance.now();
    br.rollback(ck.id);
    rbLat.push(performance.now() - tr);
  }
  console.log(`done`);
  console.log(`    rollback p50 = ${median(rbLat).toFixed(3)} ms   ` +
    `min ${Math.min(...rbLat).toFixed(3)} / max ${Math.max(...rbLat).toFixed(3)} ms (${rbSample} samples)`);

  // ---- 5. Storage: delta, not base ----
  const branchBytes = dirSize(workDir, (f) => f !== 'base.rvf' && f.endsWith('.rvf'));
  const perBranch = branchBytes / N;
  const fullCopyEquiv = baseBytes * N;
  console.log(`[5] storage`);
  console.log(`    base file            : ${fmtBytes(baseBytes)}`);
  console.log(`    ${N} branches (total) : ${fmtBytes(branchBytes)}  (${fmtBytes(perBranch)}/branch)`);
  console.log(`    N x full-copy would be: ${fmtBytes(fullCopyEquiv)}`);
  console.log(`    => branches use ${(fullCopyEquiv / branchBytes).toFixed(0)}x less disk than N full copies`);
  console.log(`    => total branch storage is ${(branchBytes / baseBytes).toFixed(2)}x the base ` +
    `(grows with DELTA, not base)`);

  // ---- verdict ----
  const pass1000 = N >= 1000;
  const correctnessOk = recall >= 0.99 && maskViolations === 0;
  console.log('\n' + '='.repeat(72));
  console.log('VERDICT');
  console.log(`  branches forked        : ${N}${pass1000 ? ' (>= 1000 target met)' : ' (below 1000 target)'}`);
  console.log(`  top-${K} correctness     : recall ${(recall * 100).toFixed(1)}%, masking ${maskViolations === 0 ? 'PASS' : 'FAIL'}`);
  console.log(`  rollback latency       : ${median(rbLat).toFixed(3)} ms p50 (~constant)`);
  console.log(`  storage vs base        : ${(branchBytes / baseBytes).toFixed(2)}x base for ${N} branches (sublinear in base)`);
  console.log(`  ACCEPTANCE: ${pass1000 && correctnessOk ? 'PASS ✓' : 'PARTIAL — see notes above'}`);
  console.log('='.repeat(72));

  // write results.json for README/site
  const out = {
    machine: os.cpus()[0].model.trim(),
    node: process.version,
    date: new Date().toISOString(),
    config: { base: BASE, branchesTarget: BRANCHES, dim: DIM, insertsPerBranch: INSERTS_PER_BRANCH, tombstonesPerBranch: TOMBSTONES_PER_BRANCH, k: K },
    branchesForked: N,
    forkMedianMs: median(forkLat),
    forkTotalMs: forkWallMs,
    recallAtK: recall,
    exactOrderMatch: exactRate,
    maskViolations,
    rollbackP50Ms: median(rbLat),
    rollbackMinMs: Math.min(...rbLat),
    rollbackMaxMs: Math.max(...rbLat),
    baseBytes,
    branchTotalBytes: branchBytes,
    perBranchBytes: perBranch,
    fullCopyEquivBytes: fullCopyEquiv,
    diskSavingsVsFullCopy: fullCopyEquiv / branchBytes,
    storageVsBaseRatio: branchBytes / baseBytes,
    pass: pass1000 && correctnessOk,
  };
  try {
    fs.writeFileSync(path.join(process.cwd(), 'bench', 'acceptance-results.json'), JSON.stringify(out, null, 2));
    console.log(`\nwrote bench/acceptance-results.json`);
  } catch (e) { console.log(`(could not write results: ${e.message})`); }

  for (const br of branches) { try { br.close(); } catch { /* */ } }
  try { base.close(); } catch { /* */ }
  fs.rmSync(workDir, { recursive: true, force: true });
  process.exit(out.pass ? 0 : 1);
}

function forkWallMsFmt(ms) { return ms < 1000 ? `${ms.toFixed(0)} ms` : `${(ms / 1000).toFixed(1)} s`; }

main().catch((e) => { console.error(e); process.exit(1); });

// agenticow — Git for Agent Memory
// Copy-On-Write vector branching for embedded multi-agent memory.
//
// Built on ruvector's RVF format via @ruvector/rvf-node. The headline capability
// is base-size-independent COW branch creation: deriving a branch off a base
// memory costs ~0.5 ms and ~162 bytes regardless of how big the base is —
// proven 83x faster and ~3000x smaller than full-copy snapshots at 1M vectors.
//
// Honest scope:
//   - Branch/checkpoint CREATE is O(edits), O(1) in base size. PROVEN.
//   - query() is an EXACT read-through: parent ∪ child-edits, child wins on an
//     id collision, deletes are honored. It works by merging each store in the
//     lineage chain (child -> ... -> base). Each store answers with its own
//     native index; agenticow merges + re-ranks exactly across the boundary.
//   - A single ANN/HNSW index that SPANS the COW boundary is NOT shipped — that
//     is roadmap. Native cluster-level read-through (branch()) landed in
//     ruvnet/RuVector PR #617; until it is published, agenticow implements the
//     read-through in this wrapper over the shipped derive() primitive.

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import pkg from '@ruvector/rvf-node';

const { RvfDatabase } = pkg;

const DEFAULT_METRIC = 'cosine';

// Process-wide monotonic counter for auto-assigned ids (the convenience
// `ingest(vec, {text})` form with no explicit id). Shared across ALL instances
// so a base and the branches forked from it never collide on an auto-id — a
// per-instance counter would hand out the same id on both sides and a later
// promote() would silently overwrite. Starts high to stay clear of typical
// caller-assigned ids. Explicit ids are unaffected, so example determinism holds.
let GLOBAL_AUTO_ID = 9_000_000_000;

/** @param {number[]|Float32Array} v */
function toF32(v) {
  return v instanceof Float32Array ? v : Float32Array.from(v);
}

// L2-normalize a copy of v. Used when metric is cosine so that ranking is
// identical whether the engine scores with cosine or L2 — important because the
// shipped rvf-node binding reopens files with the l2 metric (the cosine setting
// is not persisted). On unit vectors, L2 distance is monotonic with cosine
// distance, so top-K is preserved either way.
function l2normalize(src) {
  const v = src instanceof Float32Array ? Float32Array.from(src) : Float32Array.from(src);
  let n = 0;
  for (let i = 0; i < v.length; i++) n += v[i] * v[i];
  n = Math.sqrt(n);
  if (n > 0) for (let i = 0; i < v.length; i++) v[i] /= n;
  return v;
}

function tmpChildPath(base, label) {
  const slug = (label || 'branch').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 24) || 'branch';
  const rand = crypto.randomBytes(4).toString('hex');
  const dir = path.dirname(base);
  const stem = path.basename(base).replace(/\.rvf$/i, '');
  return path.join(dir, `${stem}.${slug}-${rand}.rvf`);
}

/**
 * One node in the COW lineage chain. `db` is an open RvfDatabase handle.
 * `tombstones` are ids deleted at this node (hide the same id in ancestors).
 */
class Node {
  constructor(db, nodePath, label) {
    this.db = db;
    this.path = nodePath;
    this.label = label || null;
    this.id = db.fileId();
    this.tombstones = new Set();
    // Audit: when this node was created (epoch ms). Surfaced via lineage() so
    // callers can build a provenance/compliance trail.
    this.createdAt = Date.now();
    // Edit log for diff()/promote(). Cheap on small branches; disabled on huge
    // bases via { track:false } in open().
    this.editIds = new Set();
    this.editVecs = new Map();
    // Optional per-id text/payload metadata (set via ingest(vec,{text}) or
    // ingest([{id,vector,text}])). Surfaced on query hits as `hit.text`.
    this.texts = new Map();
  }
}

export class AgenticMemory {
  /** @private */
  constructor(workingNode, ancestors, dim, metric, track = true, owned = null, nativeCow = false) {
    /** @type {Node} */
    this._working = workingNode;
    /** @type {Node[]} ancestors newest -> oldest (base last) */
    this._ancestors = ancestors;
    this._dim = dim;
    this._metric = metric;
    this._track = track;
    this._normalize = String(metric).toLowerCase() === 'cosine';
    // Engine metric of the underlying RVF store. For cosine we drive the engine
    // with L2 over L2-NORMALIZED vectors (L2 order == cosine order on unit
    // vectors). This is what makes BOTH the exact read-through and the native
    // COW dual-graph ANN path correct for cosine — rvf-node 0.2.0's native COW
    // query is accurate for L2 but not for the cosine metric directly.
    this._engineMetric = this._normalize ? 'l2' : String(metric).toLowerCase();
    // Nodes this instance is allowed to close. Ancestors shared from a parent
    // (via fork/branch) are NOT owned, so closing a fork never closes the base.
    /** @type {Set<Node>} */
    this._owned = owned || new Set([workingNode]);
    this._closed = false;
    /**
     * True when this instance's working node was created via RvfDatabase.branch()
     * (a real COW child with a dual-graph HNSW that spans the parent boundary).
     * When true, query() routes through the native Rust ANN path — a single
     * db.query() call returns parent∪child hits via the dual-graph merge in
     * rvf-runtime's query_via_index_cow. Verified recall@10 ≈ 1.0 (0.999,
     * 5,000-vector base ∪ 200 edits, dim 128, cosine via normalized-L2) on
     * linux-x64-gnu; degrades to the exact JS path on other platforms.
     * @type {boolean}
     */
    this._nativeCow = nativeCow;
    /**
     * The memory this instance was forked/branched from, if any. Lets
     * promote() default its target to the parent — so a documented snippet can
     * call `branch.promote()` with no argument (merge back into the base).
     * @type {AgenticMemory|null}
     */
    this._parent = null;
  }

  /**
   * Open an existing memory file, or create one if it does not exist.
   * @param {string} filePath
   * @param {{dimension?:number, metric?:string, m?:number, efConstruction?:number, track?:boolean}} [opts]
   *   track (default true): keep an in-memory edit log enabling diff()/promote().
   *   Set false on very large bases to avoid caching their vectors.
   * @returns {AgenticMemory}
   */
  static open(filePath, opts = {}) {
    let db, dim, metric;
    if (fs.existsSync(filePath)) {
      db = RvfDatabase.open(filePath);
      dim = db.dimension();
      // A reopened store reports its ENGINE metric (l2 for cosine stores). Let
      // the caller restore the user-facing metric with opts.metric — or use
      // save()/load(), which persists it. See README "Note on cosine".
      metric = opts.metric || (db.metric ? db.metric() : DEFAULT_METRIC);
    } else {
      if (!opts.dimension) {
        throw new Error('agenticow: dimension is required when creating a new memory file');
      }
      dim = opts.dimension;
      metric = opts.metric || DEFAULT_METRIC;
      // cosine -> drive the engine with l2 over normalized vectors.
      const engineMetric = String(metric).toLowerCase() === 'cosine' ? 'l2' : metric;
      db = RvfDatabase.create(filePath, {
        dimension: dim,
        metric: engineMetric,
        ...(opts.m ? { m: opts.m } : {}),
        ...(opts.efConstruction ? { efConstruction: opts.efConstruction } : {}),
      });
    }
    return new AgenticMemory(new Node(db, filePath, 'base'), [], dim, metric, opts.track !== false);
  }

  /** Full lineage chain, working node first. @returns {Node[]} */
  _chain() {
    return [this._working, ...this._ancestors];
  }

  _deriveOpts() {
    // Children must use the same ENGINE metric as the base (l2 for cosine).
    return { dimension: this._dim, metric: this._engineMetric };
  }

  _assertOpen() {
    if (this._closed) throw new Error('agenticow: memory is closed');
  }

  /**
   * Ingest vectors into the current working node.
   * Forms:
   *   ingest([{ id, vector }, ...])
   *   ingest(Float32Array, number[])   // flat batch, fastest
   * @returns {{accepted:number, rejected:number, epoch:number}}
   */
  ingest(records, ids) {
    this._assertOpen();
    // ── Convenience single-vector form: ingest(vec, {text?, id?}) ──────────
    // `vec` is a single embedding (Float32Array or number[] of length dim) and
    // the second arg is an options OBJECT (not an ids array). Auto-assigns an id
    // when none is given and records optional `text` payload. This is what lets
    // the documented snippet `branch.ingest(vec, { text })` run verbatim.
    const looksLikeVector =
      (records instanceof Float32Array || (Array.isArray(records) && typeof records[0] === 'number')) &&
      records.length === this._dim;
    const secondIsOpts =
      ids === undefined || (ids !== null && typeof ids === 'object' && !Array.isArray(ids) && !(ids instanceof Float32Array));
    if (looksLikeVector && secondIsOpts) {
      const opts = ids || {};
      const id = opts.id !== undefined ? opts.id : GLOBAL_AUTO_ID++;
      if (opts.text !== undefined) this._working.texts.set(id, opts.text);
      return this.ingest([{ id, vector: records }]);
    }

    let flat, idArr;
    if (records instanceof Float32Array) {
      flat = this._normalize ? Float32Array.from(records) : records;
      idArr = ids;
    } else if (Array.isArray(records)) {
      idArr = records.map((r) => r.id);
      flat = new Float32Array(records.length * this._dim);
      for (let i = 0; i < records.length; i++) flat.set(toF32(records[i].vector), i * this._dim);
      // record optional text payloads carried on the records
      for (const r of records) if (r.text !== undefined) this._working.texts.set(r.id, r.text);
    } else {
      throw new Error('agenticow: ingest expects an array of {id,vector} or (Float32Array, ids)');
    }
    if (this._normalize) {
      // normalize each row in place (flat is already a private copy here)
      for (let i = 0; i < idArr.length; i++) {
        const o = i * this._dim;
        let n = 0;
        for (let j = 0; j < this._dim; j++) n += flat[o + j] * flat[o + j];
        n = Math.sqrt(n);
        if (n > 0) for (let j = 0; j < this._dim; j++) flat[o + j] /= n;
      }
    }
    // A re-ingested id is no longer a delete in this node.
    for (const id of idArr) this._working.tombstones.delete(id);
    const res = this._working.db.ingestBatch(flat, idArr);
    if (this._track) {
      for (let i = 0; i < idArr.length; i++) {
        const id = idArr[i];
        this._working.editIds.add(id);
        this._working.editVecs.set(id, flat.slice(i * this._dim, (i + 1) * this._dim));
      }
    }
    return res;
  }

  /**
   * Delete ids from the current branch's view (COW tombstone). The id stays in
   * the ancestor on disk, but is hidden from this branch's reads.
   * @param {number[]} ids
   */
  delete(ids) {
    this._assertOpen();
    let deleted = 0;
    try {
      const res = this._working.db.delete(ids);
      deleted = res?.deleted ?? 0;
    } catch {
      /* id may live only in an ancestor; fall through to tombstone */
    }
    for (const id of ids) {
      this._working.tombstones.add(id);
      this._working.editIds.delete(id);
      this._working.editVecs.delete(id);
    }
    return { deleted, tombstoned: ids.length };
  }

  /**
   * EXACT read-through k-NN: parent ∪ child-edits, child wins on id collision,
   * deletes honored. Merges every node in the lineage chain and re-ranks.
   * @param {number[]|Float32Array} vector
   * @param {number} [k=10]
   * @param {{efSearch?:number, overscan?:number}} [opts]
   * @returns {{id:number, distance:number, branch:string}[]}
   */
  query(vector, k = 10, opts = {}) {
    this._assertOpen();
    // Convenience form: query(vec, { topK, efSearch?, overscan? }). When the
    // second arg is an options object, read k from topK/k. Lets the documented
    // snippet `branch.query(vec, { topK: 5 })` run verbatim.
    if (k !== null && typeof k === 'object' && !Array.isArray(k)) {
      opts = k;
      k = opts.topK ?? opts.k ?? 10;
    }
    const qv = this._normalize ? l2normalize(vector) : toF32(vector);
    const qopts = opts.efSearch ? { efSearch: opts.efSearch } : undefined;

    // ── Native COW dual-graph ANN path ────────────────────────────────
    // When this instance was created via fork({nativeAnn:true}) or
    // branch({nativeAnn:true}), the working node's db is a real COW child
    // (RvfDatabase.branch()). A single db.query() call transparently queries
    // both the child's own HNSW and the parent's HNSW, merges candidates with
    // child-wins semantics, and excludes tombstoned IDs — all in Rust.
    // Recall@10 = 1.0000 on the PR#618 integration test (1200-vector L2,
    // 60 new + 20 overrides + 10 tombstones, efSearch=300).
    if (this._nativeCow && !opts.forceExact) {
      const hits = this._working.db.query(qv, k, qopts);
      return hits.map((h) => this._withText({
        id: h.id,
        distance: h.distance,
        branch: this._working.label || this._working.id,
      }));
    }

    // ── Exact JS chain-walk (default / fallback) ──────────────────────
    // For each node in the lineage chain (newest first), query its local
    // store and merge with child-wins semantics.
    const fetch = Math.max(k, opts.overscan || k * 4);
    const resolved = new Map(); // id -> {id, distance, branch}
    const hidden = new Set(); // ids tombstoned by a nearer descendant
    for (const node of this._chain()) {
      for (const t of node.tombstones) hidden.add(t);
      let hits = [];
      try {
        hits = node.db.query(qv, fetch, qopts);
      } catch {
        hits = [];
      }
      for (const h of hits) {
        if (resolved.has(h.id) || hidden.has(h.id)) continue; // nearer node wins
        resolved.set(h.id, { id: h.id, distance: h.distance, branch: node.label || node.id });
      }
    }
    return [...resolved.values()]
      .sort((a, b) => a.distance - b.distance)
      .slice(0, k)
      .map((h) => this._withText(h));
  }

  /** Walk the lineage chain (child→base) for the text payload of an id. */
  _textFor(id) {
    for (const node of this._chain()) {
      if (node.texts.has(id)) return node.texts.get(id);
    }
    return undefined;
  }

  /** Attach a `text` field to a hit when a payload exists for its id. */
  _withText(hit) {
    const t = this._textFor(hit.id);
    return t === undefined ? hit : { ...hit, text: t };
  }

  /**
   * Whether this instance uses the native Rust COW dual-graph ANN query path.
   * true => query() routes through rvf-runtime's query_via_index_cow (PR #618).
   * false => exact JS chain-walk across the lineage.
   * @type {boolean}
   */
  get nativeAnn() {
    return this._nativeCow;
  }

  /**
   * Create an isolated COW branch (a parallel fork of this memory). O(1) in base
   * size — ~0.5 ms / 162 bytes. The branch sees everything this memory currently
   * has via read-through, plus its own future edits. Mutations are isolated:
   * neither side sees the other's later writes.
   * @param {string} [label]
   * @param {string} [filePath]
   * @returns {AgenticMemory}
   */
  branch(label, filePath) {
    this._assertOpen();
    // Freeze the current working node so BOTH sides derive off the same
    // immutable snapshot — this is what guarantees mutation isolation (neither
    // the parent nor the branch sees the other's later writes).
    const frozen = this._working;
    const parentChildPath = tmpChildPath(frozen.path, 'work');
    const parentChildDb = frozen.db.derive(parentChildPath, this._deriveOpts());
    const childPath = filePath || tmpChildPath(frozen.path, label);
    const childDb = frozen.db.derive(childPath, this._deriveOpts());
    // Parent continues, transparently, in its own fresh child (which it owns).
    this._ancestors = [frozen, ...this._ancestors];
    this._working = new Node(parentChildDb, parentChildPath, 'working');
    this._owned.add(this._working);
    // Branch shares the frozen snapshot + all older ancestors; it owns only its
    // own working child.
    const branchNode = new Node(childDb, childPath, label || 'branch');
    const child = new AgenticMemory(branchNode, [...this._ancestors], this._dim, this._metric, this._track);
    child._parent = this; // enables promote() with no explicit target
    return child;
  }

  /**
   * Lightweight fork: derive a child WITHOUT re-pointing this memory. Use this to
   * fan out many branches off a base you will not mutate again (e.g. spawn 1,000
   * per-user branches off one shared base). One derive() per fork — ~0.5 ms /
   * 162 bytes each, O(1) in base size. Read-through isolation holds as long as
   * the parent base stays read-only after forking.
   *
   * `opts.nativeAnn` (default false): when true, creates a real COW branch via
   * RvfDatabase.branch() instead of derive(). The returned fork's query() routes
   * through the native Rust dual-graph ANN merge (RuVector PR #617/#618), which
   * queries both the fork's own HNSW and the parent's HNSW in a single call —
   * sub-linear ANN ACROSS the COW boundary. Verified recall@10 ≈ 1.0 here
   * (0.999, 5,000-vector base ∪ 200 edits, dim 128, cosine via normalized-L2).
   * Platform: the native binary ships for linux-x64-gnu today; on other
   * platforms this degrades gracefully to the exact read-through path (identical
   * correctness, JS merge — `nativeAnn` will read false). Requires the parent to
   * NOT be mutated after forking (same rule as exact mode).
   * @param {string} [label]
   * @param {string} [filePath]
   * @param {{nativeAnn?:boolean}} [opts]
   * @returns {AgenticMemory}
   */
  fork(label, filePath, opts = {}) {
    this._assertOpen();
    const childPath = filePath || tmpChildPath(this._working.path, label);
    if (opts.nativeAnn) {
      // Native COW branch: the Rust COW engine wires parent→child read-through
      // so a single db.query() merges both sides via dual-graph ANN.
      // The native branch() binary ships for linux-x64-gnu today; on other
      // platforms RvfDatabase.branch() may be absent/throw — we degrade
      // gracefully to the exact read-through path (same correctness, JS merge).
      if (typeof this._working.db.branch === 'function') {
        try {
          const childDb = this._working.db.branch(childPath);
          const childNode = new Node(childDb, childPath, label || 'fork');
          // The COW child already knows its parent; no JS ancestor chain needed.
          const nativeChild = new AgenticMemory(
            childNode,
            [],  // ancestors managed by Rust COW engine
            this._dim,
            this._metric,
            this._track,
            null,
            true  // _nativeCow = true → query() uses native path
          );
          nativeChild._parent = this;
          return nativeChild;
        } catch {
          /* fall through to exact read-through */
        }
      }
      // graceful fallback (non-linux-x64, or native branch unavailable)
    }
    const childDb = this._working.db.derive(childPath, this._deriveOpts());
    const childNode = new Node(childDb, childPath, label || 'fork');
    const child = new AgenticMemory(
      childNode,
      [this._working, ...this._ancestors],
      this._dim,
      this._metric,
      this._track
    );
    child._parent = this; // enables promote() with no explicit target
    return child;
  }

  /**
   * Git-style diff of this branch's working node against its nearest ancestor:
   * which ids were added, overridden, or tombstoned. Requires edit tracking
   * (open with track !== false).
   * @returns {{added:number[], overridden:number[], deleted:number[]}}
   */
  diff() {
    this._assertOpen();
    const ancestorIds = new Set();
    for (const a of this._ancestors) for (const id of a.editIds) ancestorIds.add(id);
    const added = [];
    const overridden = [];
    for (const id of this._working.editIds) {
      (ancestorIds.has(id) ? overridden : added).push(id);
    }
    return {
      added: added.sort((a, b) => a - b),
      overridden: overridden.sort((a, b) => a - b),
      deleted: [...this._working.tombstones].sort((a, b) => a - b),
    };
  }

  /**
   * Promote (merge) this branch's recorded edits onto a target memory — the
   * Git-style "branch -> reviewed -> production" workflow. Replays the working
   * node's ingested vectors and tombstones into `target`. Requires edit tracking.
   * @param {AgenticMemory} target
   * @returns {{ingested:number, deleted:number}}
   */
  promote(target) {
    this._assertOpen();
    // Default the target to the parent this branch was forked/branched from, so
    // `branch.promote()` (no argument) merges back into its base — the verb the
    // documented snippet uses.
    target = target || this._parent;
    if (!(target instanceof AgenticMemory)) {
      throw new Error('agenticow: promote needs a target AgenticMemory (or a parent set by fork()/branch())');
    }
    const ids = [...this._working.editIds];
    if (ids.length && this._working.editVecs.size === 0) {
      throw new Error('agenticow: promote needs tracked edit vectors (open with track:true)');
    }
    if (ids.length) {
      const flat = new Float32Array(ids.length * this._dim);
      for (let i = 0; i < ids.length; i++) flat.set(this._working.editVecs.get(ids[i]), i * this._dim);
      target.ingest(flat, ids);
      // carry text payloads across the promotion
      for (const id of ids) {
        if (this._working.texts.has(id)) target._working.texts.set(id, this._working.texts.get(id));
      }
    }
    const tomb = [...this._working.tombstones];
    if (tomb.length) target.delete(tomb);
    return { ingested: ids.length, deleted: tomb.length };
  }

  /**
   * Freeze the current state as an immutable restore point and keep working in a
   * fresh COW child. O(1) in base size. Returns the checkpoint descriptor.
   * @param {string} [label]
   * @returns {{id:string, label:string, path:string, depth:number}}
   */
  checkpoint(label) {
    this._assertOpen();
    const frozen = this._working;
    frozen.label = label || frozen.label || `ckpt-${this._ancestors.length + 1}`;
    const childPath = tmpChildPath(frozen.path, 'work');
    const childDb = frozen.db.derive(childPath, this._deriveOpts());
    const childNode = new Node(childDb, childPath, 'working');
    this._ancestors = [frozen, ...this._ancestors];
    this._working = childNode;
    this._owned.add(childNode);
    return {
      id: frozen.id,
      label: frozen.label,
      path: frozen.path,
      depth: this._ancestors.length,
    };
  }

  /**
   * Discard all edits since a checkpoint and resume from it. With no argument,
   * rolls back to the most recent checkpoint. Abandons the poisoned working
   * child and derives a fresh writable child off the chosen checkpoint.
   * @param {string} [checkpointId] fileId of the checkpoint to return to
   * @returns {{restoredTo:string, depth:number}}
   */
  rollback(checkpointId) {
    this._assertOpen();
    if (this._ancestors.length === 0) {
      throw new Error('agenticow: nothing to roll back to (no checkpoints)');
    }
    let idx = 0; // default: most recent checkpoint
    if (checkpointId) {
      idx = this._ancestors.findIndex((n) => n.id === checkpointId);
      if (idx === -1) throw new Error(`agenticow: checkpoint ${checkpointId} not found`);
    }
    // Discard the current poisoned working child and any checkpoints newer than
    // target — but only ones THIS instance owns (never a shared ancestor).
    const discarded = [this._working, ...this._ancestors.slice(0, idx)];
    for (const n of discarded) {
      if (!this._owned.has(n)) continue;
      try { n.db.close(); } catch { /* ignore */ }
      try { fs.rmSync(n.path, { force: true }); } catch { /* ignore */ }
      this._owned.delete(n);
    }
    const target = this._ancestors[idx];
    const newAncestors = this._ancestors.slice(idx); // target + older
    const childPath = tmpChildPath(target.path, 'work');
    const childDb = target.db.derive(childPath, this._deriveOpts());
    this._working = new Node(childDb, childPath, 'working');
    this._owned.add(this._working);
    this._ancestors = newAncestors;
    return { restoredTo: target.id, depth: this._ancestors.length };
  }

  /** Lineage chain metadata, working node first. */
  lineage() {
    const chain = this._chain();
    return chain.map((n, i) => ({
      role: i === 0 ? 'working' : (i === chain.length - 1 ? 'base' : 'checkpoint'),
      id: n.id,
      label: n.label,
      path: n.path,
      parent: i < chain.length - 1 ? chain[i + 1].id : null,
      createdAt: n.createdAt,
      mutations: n.editIds.size,
      tombstones: n.tombstones.size,
    }));
  }

  /** Status of the working node plus chain depth. */
  status() {
    this._assertOpen();
    const s = this._working.db.status();
    return {
      ...s,
      chainDepth: this._chain().length,
      dimension: this._dim,
      metric: this._metric,
    };
  }

  /** dimension of stored vectors */
  get dimension() {
    return this._dim;
  }

  /**
   * Persist the lineage to a small JSON manifest so the CLI (or another process)
   * can reopen the exact chain. Vector data stays in the .rvf files; the manifest
   * holds the chain order, labels, tombstones and (for diff/promote) the working
   * node's recorded edits.
   * @param {string} manifestPath
   */
  save(manifestPath) {
    this._assertOpen();
    const nodes = this._chain().map((n, i) => ({
      path: path.resolve(n.path),
      label: n.label,
      tombstones: [...n.tombstones],
      // only the working node (i===0) needs its edit vectors for promote()
      editIds: i === 0 ? [...n.editIds] : [],
      editVecs: i === 0 ? Object.fromEntries([...n.editVecs].map(([id, v]) => [id, Array.from(v)])) : {},
      // Per-id text payloads (surfaced on query hits via _textFor's chain
      // walk). Persisted for EVERY node — a payload ingested on an ancestor
      // must survive save/load or query hits from that node lose their text.
      texts: Object.fromEntries([...n.texts]),
    }));
    // v2 adds per-node `texts`. load() reads `nm.texts || {}`, so v1 manifests
    // (no texts) still load — forward-compatible, no migration needed.
    fs.writeFileSync(manifestPath, JSON.stringify({ v: 2, dim: this._dim, metric: this._metric, track: this._track, nodes }, null, 2));
    return manifestPath;
  }

  /**
   * Reconstruct an AgenticMemory from a manifest written by save().
   * @param {string} manifestPath
   * @returns {AgenticMemory}
   */
  static load(manifestPath) {
    const m = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
    const nodes = m.nodes.map((nm, i) => {
      const db = i === 0 ? RvfDatabase.open(nm.path) : RvfDatabase.openReadonly(nm.path);
      const node = new Node(db, nm.path, nm.label);
      node.tombstones = new Set(nm.tombstones || []);
      node.editIds = new Set(nm.editIds || []);
      node.editVecs = new Map(Object.entries(nm.editVecs || {}).map(([id, v]) => [Number(id), Float32Array.from(v)]));
      // Restore text payloads (v2 manifest). v1 manifests have no `texts`
      // key → empty Map, matching pre-fix behavior for old files.
      node.texts = new Map(Object.entries(nm.texts || {}).map(([id, t]) => [Number(id), t]));
      return node;
    });
    // A loaded instance opened every handle itself, so it owns the whole chain.
    return new AgenticMemory(nodes[0], nodes.slice(1), m.dim, m.metric, m.track !== false, new Set(nodes));
  }

  /** Close the handles this instance owns (never a shared parent/base handle). */
  close() {
    if (this._closed) return;
    for (const n of this._owned) {
      try { n.db.close(); } catch { /* ignore */ }
    }
    this._closed = true;
  }
}

/** Convenience: open or create a memory. @see AgenticMemory.open */
export function open(filePath, opts) {
  return AgenticMemory.open(filePath, opts);
}

/**
 * Alias of {@link open}. Provided so documented snippets that read
 * `import { openBase } from 'agenticow'` run verbatim. Identical behavior.
 */
export const openBase = open;

export default { open, openBase, AgenticMemory };

#!/usr/bin/env node
// agenticow benchmark — reproduces the COW branch-CREATE advantage honestly.
//
// What this measures (and what it does NOT):
//   - COW branch CREATE: time + on-disk delta size to derive() a branch off a
//     base of N vectors. This is the headline, base-size-INDEPENDENT primitive.
//   - Naive FULL COPY: time + bytes to byte-copy the whole base .rvf file (the
//     baseline every other vector store forces you into for a snapshot).
//   - Speed/size ratios at each base size.
//
// Honest caveats (printed in the footer):
//   - This benchmarks branch CREATION, not query throughput.
//   - Branch delta = O(edits), 162 B empty + ~520 B/edited-vector, independent
//     of base size. Full copy = O(base file).
//   - ANN query that spans the COW boundary is NOT benchmarked (roadmap). The
//     shipped read-through is exact (parent ∪ edits) and lives in the lib layer.
//
// Usage:
//   node bench/bench.js                 # 10k + 100k (fast, default)
//   SIZES=10000,100000,1000000 node bench/bench.js   # include the 1M row (slow)
//   DIM=128 node bench/bench.js

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { performance } from 'node:perf_hooks';
import pkg from '@ruvector/rvf-node';

const { RvfDatabase } = pkg;

const DIM = Number(process.env.DIM || 128);
const METRIC = 'cosine';
const SIZES = (process.env.SIZES || '10000,100000')
  .split(',')
  .map((s) => parseInt(s.trim(), 10))
  .filter(Boolean);
const REPEAT = Number(process.env.REPEAT || 11); // odd -> clean median
const EDIT_COUNTS = [0, 10, 100, 1000];

const workDir = fs.mkdtempSync(path.join(os.tmpdir(), 'agenticow-bench-'));

function rndVec() {
  const v = new Float32Array(DIM);
  for (let i = 0; i < DIM; i++) v[i] = Math.random() * 2 - 1;
  return v;
}
function median(xs) {
  const s = [...xs].sort((a, b) => a - b);
  return s[Math.floor(s.length / 2)];
}
function fmtBytes(b) {
  if (b < 1024) return `${b} B`;
  if (b < 1024 * 1024) return `${(b / 1024).toFixed(1)} KB`;
  return `${(b / 1024 / 1024).toFixed(1)} MB`;
}
function fmtMs(ms) {
  return ms < 1 ? `${(ms * 1000).toFixed(0)} µs` : `${ms.toFixed(2)} ms`;
}

function buildBase(n) {
  const basePath = path.join(workDir, `base-${n}.rvf`);
  fs.rmSync(basePath, { force: true });
  const db = RvfDatabase.create(basePath, { dimension: DIM, metric: METRIC });
  const BATCH = 10000;
  let done = 0;
  while (done < n) {
    const m = Math.min(BATCH, n - done);
    const flat = new Float32Array(m * DIM);
    const ids = new Array(m);
    for (let i = 0; i < m; i++) {
      flat.set(rndVec(), i * DIM);
      ids[i] = done + i;
    }
    db.ingestBatch(flat, ids);
    done += m;
  }
  db.close();
  return basePath;
}

// COW branch CREATE: median latency over REPEAT derives, plus delta size for
// each edit count.
function benchBranchCreate(basePath) {
  const base = RvfDatabase.open(basePath);
  const lat = [];
  for (let r = 0; r < REPEAT; r++) {
    const childPath = path.join(workDir, `br-${r}-${Math.random().toString(36).slice(2)}.rvf`);
    const t0 = performance.now();
    const child = base.derive(childPath, { dimension: DIM, metric: METRIC });
    const t1 = performance.now();
    lat.push(t1 - t0);
    child.close();
    fs.rmSync(childPath, { force: true });
  }
  // delta sizes by edit count (apply edits to a fresh branch each time)
  const sizes = {};
  for (const ec of EDIT_COUNTS) {
    const childPath = path.join(workDir, `brsize-${ec}.rvf`);
    fs.rmSync(childPath, { force: true });
    const child = base.derive(childPath, { dimension: DIM, metric: METRIC });
    if (ec > 0) {
      const flat = new Float32Array(ec * DIM);
      const ids = new Array(ec);
      for (let i = 0; i < ec; i++) {
        flat.set(rndVec(), i * DIM);
        ids[i] = 1_000_000_000 + i; // new ids -> pure additions
      }
      child.ingestBatch(flat, ids);
    }
    child.close();
    sizes[ec] = fs.statSync(childPath).size;
    fs.rmSync(childPath, { force: true });
  }
  base.close();
  return { latency: median(lat), sizes };
}

// Naive FULL COPY baseline: byte-copy the whole base file (what a snapshot costs
// without COW). Median over REPEAT copies.
function benchFullCopy(basePath) {
  const baseSize = fs.statSync(basePath).size;
  const lat = [];
  for (let r = 0; r < REPEAT; r++) {
    const dst = path.join(workDir, `copy-${r}.rvf`);
    const t0 = performance.now();
    fs.copyFileSync(basePath, dst);
    const t1 = performance.now();
    lat.push(t1 - t0);
    fs.rmSync(dst, { force: true });
  }
  return { latency: median(lat), size: baseSize };
}

function main() {
  console.log('agenticow — COW branch-create benchmark');
  console.log('='.repeat(72));
  console.log(`machine : ${os.cpus()[0].model.trim()} (${os.cpus().length} threads)`);
  console.log(`node    : ${process.version}   platform: ${process.platform}-${process.arch}`);
  console.log(`vectors : dim=${DIM}  metric=${METRIC}  median of ${REPEAT} runs`);
  console.log('='.repeat(72));

  const rows = [];
  for (const n of SIZES) {
    process.stdout.write(`\nbuilding base of ${n.toLocaleString()} vectors ... `);
    const basePath = buildBase(n);
    const baseSize = fs.statSync(basePath).size;
    console.log(`${fmtBytes(baseSize)}`);
    const branch = benchBranchCreate(basePath);
    const copy = benchFullCopy(basePath);
    const speedup = copy.latency / branch.latency;
    const shrink = copy.size / branch.sizes[0];
    rows.push({ n, baseSize, branch, copy, speedup, shrink });
    fs.rmSync(basePath, { force: true });
    console.log(
      `  branch create : ${fmtMs(branch.latency)}  (empty delta ${fmtBytes(branch.sizes[0])})`
    );
    console.log(`  full copy     : ${fmtMs(copy.latency)}  (${fmtBytes(copy.size)})`);
    console.log(
      `  => ${speedup.toFixed(0)}x faster, ${Math.round(shrink).toLocaleString()}x smaller`
    );
  }

  // Markdown table
  console.log('\n\nResults table (Markdown)');
  console.log('-'.repeat(72));
  console.log(
    '| Base N | Base file | Branch create (p50) | Empty branch | 100-edit branch | Full copy (p50) | Speedup | Shrink |'
  );
  console.log(
    '|-------:|----------:|--------------------:|-------------:|----------------:|----------------:|--------:|-------:|'
  );
  for (const r of rows) {
    console.log(
      `| ${r.n.toLocaleString()} | ${fmtBytes(r.baseSize)} | ${fmtMs(r.branch.latency)} | ${fmtBytes(
        r.branch.sizes[0]
      )} | ${fmtBytes(r.branch.sizes[100])} | ${fmtMs(r.copy.latency)} | ${r.speedup.toFixed(
        0
      )}x | ${Math.round(r.shrink).toLocaleString()}x |`
    );
  }

  // Delta-size-vs-edits (should be flat across base sizes)
  console.log('\nBranch delta size by edit count (independent of base size):');
  console.log('| Edits | ' + rows.map((r) => `${r.n.toLocaleString()}`).join(' | ') + ' |');
  console.log('|------:|' + rows.map(() => '----------:').join('|') + '|');
  for (const ec of EDIT_COUNTS) {
    console.log(
      `| ${ec} | ` + rows.map((r) => fmtBytes(r.branch.sizes[ec])).join(' | ') + ' |'
    );
  }

  console.log('\nHonest notes:');
  console.log('  - Measures branch CREATION (derive), not query throughput.');
  console.log('  - Branch delta = O(edits), ~520 B/edited vector, flat in base size.');
  console.log('  - Full copy = O(base file). The COW advantage widens with base size.');
  console.log('  - Exact read-through (parent ∪ edits, child wins) is in the lib layer;');
  console.log('    a single ANN index spanning the COW boundary is roadmap, not shipped.');

  // JSON for the site/README
  const out = path.join(process.cwd(), 'bench', 'results.json');
  try {
    fs.writeFileSync(
      out,
      JSON.stringify(
        {
          machine: os.cpus()[0].model.trim(),
          threads: os.cpus().length,
          node: process.version,
          dim: DIM,
          metric: METRIC,
          repeat: REPEAT,
          date: new Date().toISOString(),
          rows: rows.map((r) => ({
            n: r.n,
            baseSize: r.baseSize,
            branchCreateMs: r.branch.latency,
            emptyBranchBytes: r.branch.sizes[0],
            edit100Bytes: r.branch.sizes[100],
            fullCopyMs: r.copy.latency,
            fullCopyBytes: r.copy.size,
            speedup: r.speedup,
            shrink: r.shrink,
            sizesByEdits: r.branch.sizes,
          })),
        },
        null,
        2
      )
    );
    console.log(`\nwrote ${out}`);
  } catch (e) {
    console.log(`\n(could not write results.json: ${e.message})`);
  }

  fs.rmSync(workDir, { recursive: true, force: true });
}

main();
